"""Multi-line text composition node."""

from __future__ import annotations

from typing import Any

DEFAULT_SYSTEM_PROMPT = "你是一个专业的提示词工程助手，请严格按照用户的要求输出结果。"


class QQMultiLineText:
    """Compose a system prompt, a separator and free text into one string."""

    CATEGORY = "QQ/工具"
    FUNCTION = "compose"
    RETURN_TYPES = ("STRING",)
    RETURN_NAMES = ("文本",)
    DESCRIPTION = (
        "系统提示词 + 分隔符 + 自由文本 的多行文本节点；"
        "分隔符上下自动加空行；首行开关可隐藏系统提示词框，隐藏不影响输出；"
        "全部内容随工作流保存。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "隐藏提示词": ("BOOLEAN", {"default": False}),
                "系统提示词": ("STRING", {"default": DEFAULT_SYSTEM_PROMPT, "multiline": True}),
                "自由文本": ("STRING", {"default": "", "multiline": True}),
                "分隔符": ("STRING", {"default": "", "multiline": False}),
            },
        }

    def compose(
        self,
        隐藏提示词: bool = False,
        系统提示词: str = "",
        自由文本: str = "",
        分隔符: str = "",
        **_kwargs: Any,
    ):
        text = f"{系统提示词}\n\n{分隔符}\n\n{自由文本}"
        return (text,)


_SEPARATOR_ESCAPES = {"\\n": "\n", "\\r": "\r", "\\t": "\t", "\\\\": "\\"}


def decode_separator(text: str) -> str:
    """把分隔符里的转义写法还原成真字符：\\n → 换行、\\r → 回车、\\t → 制表符、\\\\ → 反斜杠。

    单趟从左到右扫描，所以 ``\\\\n`` 会还原成「反斜杠 + n」而不是换行；
    其它反斜杠组合（如 ``\\d``）原样保留。
    """
    out: list[str] = []
    index = 0
    while index < len(text):
        char = text[index]
        if char == "\\" and index + 1 < len(text):
            pair = text[index : index + 2]
            if pair in _SEPARATOR_ESCAPES:
                out.append(_SEPARATOR_ESCAPES[pair])
                index += 2
                continue
        out.append(char)
        index += 1
    return "".join(out)


class QQTextMerge:
    """把两段文本用一个可转义的分隔符拼成一段。"""

    CATEGORY = "QQ/工具"
    FUNCTION = "merge"
    RETURN_TYPES = ("STRING",)
    RETURN_NAMES = ("文本",)
    DESCRIPTION = (
        "把 文本1 和 文本2 用 分隔符 拼成一段输出，分隔符在中间。"
        "分隔符支持转义写法：\\n 换行、\\r 回车、\\t 制表符、\\\\ 反斜杠，其它内容原样保留。"
        "两个输入口都是可选的纯输入口：只接一个时原样输出那一段，不会多出分隔符。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "分隔符": (
                    "STRING",
                    {
                        "default": "\\n",
                        "multiline": False,
                        "tooltip": "支持转义：\\n 换行、\\r 回车、\\t 制表符、\\\\ 反斜杠。",
                    },
                ),
            },
            "optional": {
                "文本1": ("STRING", {"forceInput": True}),
                "文本2": ("STRING", {"forceInput": True}),
            },
        }

    def merge(self, 分隔符: str = "", **kwargs: Any):
        parts = [str(kwargs[name]) for name in ("文本1", "文本2") if kwargs.get(name) is not None]
        return (decode_separator(str(分隔符 or "")).join(parts),)


NODE_CLASS_MAPPINGS = {"QQMultiLineText": QQMultiLineText, "QQTextMerge": QQTextMerge}
NODE_DISPLAY_NAME_MAPPINGS = {"QQMultiLineText": "QQ-多行文本", "QQTextMerge": "QQ-文本合并"}
